import Ajv from 'ajv';
import type {ValidateFunction, ErrorObject} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  if (typeof response === 'string') {
    return {result: response};
  }
  return response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private readonly ajv = new (Ajv as any)({strict: false, validateFormats: false});
  private readonly functionSchemaValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let staticValidator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      staticValidator = this.compileSchema(resolved.inputSchema, resolved.name);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
  }

  private compileSchema(schema: Record<string, unknown>, toolName: string): ValidateFunction {
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      return this.ajv.compile(schema) as any;
    } catch (error) {
      const err = new Error(`Failed to compile schema for tool "${toolName}": ${String(error)}`);
      err.cause = error;
      throw err;
    }
  }

  private getOrCompileValidator(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.staticValidator) {
      return tool.staticValidator;
    }

    const cached = this.functionSchemaValidators.get(definition.inputSchema);
    if (cached) {
      return cached;
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const compiled = this.ajv.compile(definition.inputSchema) as any;
    const validator = compiled as ValidateFunction;
    this.functionSchemaValidators.set(definition.inputSchema, validator);
    return validator;
  }

  private formatValidationErrors(validator: ValidateFunction): string {
    const errors = validator.errors ?? [];
    const messages = errors.map((error: ErrorObject) => {
      const keyword = error.keyword;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const params = error.params as any;

      if (keyword === 'required' && params?.missingProperty) {
        return `Missing required property: ${params.missingProperty as string}`;
      }

      if (keyword !== 'type' || !params?.type) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const path = (error as any).instancePath || '/';
        return `Validation failed at ${path}: ${keyword}`;
      }

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const path = (error as any).instancePath || '';
      let propertyName: string | undefined;

      if (path && path !== '/') {
        const parts = path.split('/').filter(Boolean);
        propertyName = parts[0];
      }

      if (!propertyName) {
        const schemaPath = error.schemaPath;
        const parts = schemaPath.split('/');
        const propsIndex = parts.indexOf('properties');
        const canExtractProp = propsIndex >= 0 && propsIndex + 1 < parts.length;
        propertyName = canExtractProp ? parts[propsIndex + 1] : propertyName;
      }

      propertyName = propertyName || 'value';
      return `Property ${propertyName} has wrong type (expected ${params.type as string})`;
    });
    return messages.join('; ');
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  // Validates input against the tool's inputSchema before invoking the executor; returns a rejection as a ToolResponse instead of throwing (see specs/hal-engine-tool-input-validation/spec.md).
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.getOrCompileValidator(tool, definition);

    if (!validator(input)) {
      return {result: this.formatValidationErrors(validator)};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

