  it('returns a schema rejection as a tool_result so the model can correct the call on the next round', async () => {
    const registry = new ToolRegistry();
    let executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        executorInputs.push(input);
        return `Weather in ${String(input.location)}`;
      }
    );

    let firstRoundRejectionText = '';
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        if (round === 2) {
          // Capture the rejection sent back to the provider
          const lastMessage = params.messages[params.messages.length - 1];
          if (lastMessage.role === 'user' && Array.isArray(lastMessage.content)) {
            const firstToolResult = lastMessage.content[0];
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            firstRoundRejectionText = (firstToolResult as any).content ?? '';
          }
          // Now send a corrected tool call
          yield {type: 'tool_use', toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        yield {type: 'text', text: 'Got the weather'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const result = await orchestrator.processMessage(createSession('What is the weather?'));

    expect({
      result,
      executorCalledOnce: executorInputs.length === 1,
      rejectionMentionsLocation: firstRoundRejectionText.includes('location'),
      rejectionMentionsRequired: /required/i.test(firstRoundRejectionText),
    }).toEqual({
      result: 'Got the weather',
      executorCalledOnce: true,
      rejectionMentionsLocation: true,
      rejectionMentionsRequired: true,
    });
  });
});

